export const UPDATE_RETRY_MS = 6 * 60 * 60 * 1000;
export const UPDATE_CHECK_INTERVAL_MS = 30 * 60 * 1000;
const APK_URL = 'https://github.com/v1-byte/Miko-Ai/releases/download/latest/Miko-AI-main.apk';

/** Extracts an update only from the release generated by this repository's workflow. */
export function findUpdate(localBuild, release) {
  if (!localBuild || typeof localBuild.commit !== 'string' || !release || typeof release.body !== 'string') return null;
  const match = release.body.match(/Build otomatis dari commit\s+`([0-9a-f]{40})`/i);
  if (!match) return null;
  const commit = match[1].toLowerCase();
  if (commit === localBuild.commit.trim().toLowerCase()) return null;
  const apk = Array.isArray(release.assets)
    ? release.assets.find((asset) => asset?.name === 'Miko-AI-main.apk' && asset?.browser_download_url === APK_URL)
    : null;
  if (!apk) return null;
  return { commit, url: APK_URL };
}

/** Avoids repeated download prompts for the same release while allowing a later retry. */
export function canAttemptUpdate(previousAttempt, targetCommit, now = Date.now(), cooldownMs = UPDATE_RETRY_MS) {
  if (!previousAttempt) return true;
  try {
    const previous = JSON.parse(previousAttempt);
    if (previous.commit !== targetCommit || !Number.isFinite(previous.at)) return true;
    return now - previous.at >= cooldownMs;
  } catch {
    return true;
  }
}
